const reponse=$input.first().json;
if(reponse.stop_reason==='max_tokens')throw new Error('Tri éditorial : réponse tronquée par la limite de sortie. Aucun candidat validé.');
const base=$('PREPARER SELECTION EDITORIALE').first().json.candidats;
