 if(!e || !map.has(e.cle_unique) || seen.has(e.cle_unique))throw new Error('Tri éditorial : identifiant inconnu ou répété.');
 seen.add(e.cle_unique);
 if(typeof e.pertinent!=='boolean'||typeof e.personne_physique!=='boolean'||typeof e.francais!=='boolean'||typeof e.raison!=='string'||!e.raison.trim())throw new Error('Tri éditorial : évaluation incomplète.');
 if(e.pertinent===true&&e.personne_physique===true&&e.francais===true)out.push({json:{...map.get(e.cle_unique),raison_selection:e.raison},pairedItem:{item:0}});
}
if(seen.size!==base.length)throw new Error('Tri éditorial : candidats non évalués.');
